class METSendSalesOrderInvoiceBusinessEventController extends SysOperationServiceController
{

}

Method.Source:
/// <summary>
/// Description
/// </summary>
/// <returns>class description</returns>
public static ClassDescription description()
{
    return "@MET:SOInvoiceNotification";
}

/// <summary>
/// dialog caption
/// </summary>
/// <param name="_dialogCaption">A <c>LabelType</c> Extended Data Type.</param>
/// <returns>A <c>LabelType</c> Extended Data Type.</returns>
// Caption shown on the Dialog.
public LabelType parmDialogCaption(LabelType _dialogCaption = dialogCaption)
{
    return METSendSalesOrderInvoiceBusinessEventController::description();
}

    /// <summary>
    /// create new instance of the class
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METSendSalesOrderInvoiceBusinessEventService));
        this.parmMethodName(methodStr(METSendSalesOrderInvoiceBusinessEventService, process));
    }

/// <summary>
/// Constructor method to create new instance of the class
/// </summary>
/// <returns>
/// An object of the <c>METCBCTInvoicePostingController</c> class.
/// </returns>
public static METSendSalesOrderInvoiceBusinessEventController construct()
{
    return new METSendSalesOrderInvoiceBusinessEventController();
}

/// <summary>
/// Main controller method
/// parmShowDialog is true by default
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METSendSalesOrderInvoiceBusinessEventController controller = METSendSalesOrderInvoiceBusinessEventController::construct();
    
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.startOperation();
}

/// <summary>
/// Can run in new session
/// </summary>
/// <returns>
/// true if can run in new session; otherwise, false.
/// </returns>
protected boolean canRunInNewSession()
{
    return true;
}
